import{_ as i,y as s,a as g,o as l,a2 as r,D as a,g as e,I as o}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Generate Text Content","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/generate-content.md","filePath":"generative-ai/generate-content.md","lastUpdated":1789441803000}'),d={name:"generative-ai/generate-content.md"};function h(p,t,c,u,m,f){const n=s("ImagePopup");return l(),g("div",null,[t[3]||(t[3]=r('<h1 id="generate-text-content" tabindex="-1">Generate Text Content <a class="header-anchor" href="#generate-text-content" aria-label="Permalink to &quot;Generate Text Content&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Admin panel</span></div><p>Magic AI writes text for you inside the admin&#39;s rich-text editor. You describe what you need in a prompt and check the draft in a dialog. The draft goes into the editor only when you apply it. It&#39;s a quick way to get a first draft of a product description, a category introduction, a CMS page or a marketing email.</p><h2 id="where-the-magic-ai-button-appears" tabindex="-1">Where the Magic AI button appears <a class="header-anchor" href="#where-the-magic-ai-button-appears" aria-label="Permalink to &quot;Where the Magic AI button appears&quot;">​</a></h2><p>The <strong>Magic AI</strong> button sits in the toolbar of every rich-text editor in the admin panel:</p><ul><li><strong>Catalog &gt;&gt; Products</strong>: the <strong>Short Description</strong> and <strong>Description</strong> fields, and any other text area attribute that uses the editor.</li><li><strong>Catalog &gt;&gt; Categories</strong>: the <strong>Description</strong> field.</li><li><strong>CMS</strong>: the page <strong>Content</strong>.</li><li><strong>Marketing &gt;&gt; Communications &gt;&gt; Email Templates</strong>: the template <strong>Content</strong>.</li><li><strong>Configure</strong>: text fields that use the editor, such as the GDPR agreement text.</li></ul><p>The button is greyed out until Magic AI and text generation are both switched on.</p>',7)),a(n,{src:"/images/generative-ai/description-magicai.png",alt:"The Magic AI button in the toolbar of a product's Description editor"}),t[4]||(t[4]=e("h2",{id:"generate-text",tabindex:"-1"},[o("Generate text "),e("a",{class:"header-anchor",href:"#generate-text","aria-label":'Permalink to "Generate text"'},"​")],-1)),e("ol",null,[t[1]||(t[1]=r("<li><p>Open the item you&#39;re editing, for example a product under <strong>Catalog &gt;&gt; Products</strong>.</p></li><li><p>In the editor&#39;s toolbar, click <strong>Magic AI</strong>. The <strong>AI Assistance</strong> dialog opens.</p></li><li><p>In <strong>Prompt</strong>, describe what to write. For example: &quot;Write a 120-word product description for a men&#39;s blue zipper hoodie made of soft cotton fleece, with a relaxed fit and two front pockets. Use a warm, friendly tone.&quot;</p></li><li><p>Choose the <strong>Model</strong>, for example <strong>OpenAI: GPT-5.2</strong>. The list holds the text models of the providers allowed for text generation.</p></li>",4)),e("li",null,[t[0]||(t[0]=e("p",null,[o("Click "),e("strong",null,"Generate"),o(". The button reads "),e("strong",null,"Generating..."),o(" while the model works. The draft then appears in "),e("strong",null,"Generated Content"),o(".")],-1)),a(n,{src:"/images/generative-ai/textgeneration.png",alt:"The AI Assistance dialog with a prompt, the Model list, the Generate button and an empty Generated Content box"})]),t[2]||(t[2]=r("<li><p>Read the draft. Edit it in <strong>Generated Content</strong>, or change the prompt and click <strong>Generate</strong> again.</p></li><li><p>Click <strong>Apply</strong>. The draft goes into the editor and the dialog closes.</p></li><li><p>Check the text in the editor, then save the item, for example with <strong>Save Product</strong>.</p></li>",3))]),t[5]||(t[5]=r('<p>If the provider returns an error, for example because its API key is missing, the error message appears at the top of the screen and <strong>Generated Content</strong> stays empty.</p><h3 id="apply-replaces-what-s-in-the-editor" tabindex="-1">Apply replaces what&#39;s in the editor <a class="header-anchor" href="#apply-replaces-what-s-in-the-editor" aria-label="Permalink to &quot;Apply replaces what&#39;s in the editor&quot;">​</a></h3><p><strong>Apply</strong> replaces everything in the editor with the draft, including text you wrote before. Line breaks in the draft become line breaks in the editor. If you want to keep existing text, copy it first, or include it in your prompt and ask the model to improve it.</p><h2 id="write-a-good-prompt" tabindex="-1">Write a good prompt <a class="header-anchor" href="#write-a-good-prompt" aria-label="Permalink to &quot;Write a good prompt&quot;">​</a></h2><ul><li><strong>Say what the text is for and how long it should be</strong>: a product description, a category introduction, a 200-word page.</li><li><strong>Give the facts the model can&#39;t know</strong>: materials, sizes, what&#39;s in the box, who the product is for.</li><li><strong>Ask for a tone</strong>: warm, technical, playful.</li><li><strong>Check the result.</strong> The dialog warns: &quot;AI-generated content may be misleading. Review the generated content before applying.&quot; Check names, numbers and claims before you apply the text.</li></ul><h2 id="what-you-control" tabindex="-1">What you control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What you control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong></td><td>Switches every Magic AI feature on or off</td></tr><tr><td><strong>Enabled</strong> in the <strong>Text Generation</strong> section of <strong>Configure &gt;&gt; Magic AI &gt;&gt; Admin Features</strong></td><td>Turns the <strong>Magic AI</strong> button in the editors on</td></tr><tr><td><strong>Providers</strong> in the <strong>Text Generation</strong> section</td><td>Decides which providers&#39; models appear in <strong>Model</strong></td></tr><tr><td><strong>API Key</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; Providers</strong></td><td>Connects each provider you use</td></tr></tbody></table><p>If the <strong>Model</strong> field is missing from the dialog, no provider is chosen for text generation yet. To set everything up, see <a href="./../configure/magic-ai.html#enable-the-admin-features">Enable the admin features</a>.</p><p>Each request is sent to the provider of the model you chose and billed by that provider, unless the model runs on your own Ollama server.</p>',9))])}const y=i(d,[["render",h]]);export{_ as __pageData,y as default};
